# Implement and test the isolation-based transformation
def transform(grid):
    """Transform isolated cells of the dominant color to 1."""
    H, W = len(grid), len(grid[0])

    # Find dominant color
    counts = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    if not counts:
        return grid

    target = max(counts, key=counts.get)

    # Build result
    result = [row[:] for row in grid]

    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val == target:
                # Check if isolated (no same-color neighbor)
                has_neighbor = False
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if grid[nr][nc] == val:
                            has_neighbor = True
                            break

                if not has_neighbor:
                    result[r][c] = 1

    return result

