def transform_transition(grid):
    """Transform: after first color transition in row, change everything from there to 1."""
    H, W = len(grid), len(grid[0])

    result = [row[:] for row in grid]

    for r in range(H):
        row = grid[r]

        start_val = row[0]
        first_change = None

        for c in range(1, W):
            if row[c] != start_val:
                first_change = c
                break

        if first_change is not None:
            for c in range(first_change, W):
                result[r][c] = 1

    return result

# Test on demo 1
